insert into public.taxa (id, korean_name, scientific_name, category, confusable_ids, clue, month_counts, photo, photo_license, cultivated, minor) values ('great-crested-grebe', '뿔논병아리', 'Podiceps cristatus', 'waterbird', array['common-merganser', 'eurasian-coot']::text[], '{"zoneIds":["Z1"],"where":"호수 가운데에서 헤엄치다 잠수해요.","looks":["목이 길고 앞쪽이 하얘요.","부리가 뾰족해요."]}'::jsonb, array[0, 1, 1, 3, 0, 1, 1, 2, 0, 1, 0, 2]::integer[], '{"src":"/photos/great-crested-grebe-1.webp","credit":"caroline legg","license":"CC BY 2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Great_Crested_Grebe_(52909695022).jpg"}'::jsonb, 'CC BY 2.0', false, false)
