insert into public.taxa (id, korean_name, scientific_name, category, confusable_ids, clue, month_counts, photo, photo_license, cultivated, minor) values ('mallard', '청둥오리', 'Anas platyrhynchos', 'waterbird', array['spot-billed-duck', 'common-merganser']::text[], '{"zoneIds":["Z1"],"where":"호숫가 물 위에서 쉬어요.","looks":["수컷은 머리가 초록색이에요.","암컷은 온몸이 얼룩덜룩한 갈색이에요."]}'::jsonb, array[1, 0, 0, 0, 0, 1, 0, 1, 0, 1, 0, 0]::integer[], '{"src":"/photos/mallard-1.webp","credit":"Rolf Dietrich Brecher from Germany","license":"CC BY 2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Anas_platyrhynchos_(mixed_pair)_(32428014687).jpg"}'::jsonb, 'CC BY 2.0', false, true)
