insert into public.taxa (id, korean_name, scientific_name, category, confusable_ids, clue, month_counts, photo, photo_license, cultivated, minor) values ('oriental-magpie', '까치', 'Pica serica', 'townbird', array['large-billed-crow', 'brown-eared-bulbul']::text[], '{"zoneIds":["Z4","Z5","Z6"],"where":"나무 위나 잔디밭에서 걸어 다녀요.","looks":["몸은 까맣고 배는 하얘요.","꼬리가 길어요.","깍깍 하고 울어요."]}'::jsonb, array[1, 0, 0, 1, 0, 0, 0, 1, 0, 3, 3, 3]::integer[], '{"src":"/photos/oriental-magpie-1.webp","credit":"Daniel Case","license":"CC BY-SA 3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Oriental_Magpie_on_Longevity_Hill,_Beijing.jpg"}'::jsonb, 'CC BY-SA 3.0', false, false)
