insert into public.taxa (id, korean_name, scientific_name, category, confusable_ids, clue, month_counts, photo, photo_license, cultivated, minor) values ('daurian-redstart', '딱새', 'Phoenicurus auroreus', 'townbird', array['red-flanked-bluetail', 'varied-tit']::text[], '{"zoneIds":["Z4","Z3"],"where":"낮은 나뭇가지나 울타리에 앉아요.","looks":["날개에 흰 점이 있어요.","배는 주황색이에요.","꼬리를 바르르 떨어요."]}'::jsonb, array[3, 0, 0, 1, 1, 2, 0, 0, 2, 1, 1, 1]::integer[], '{"src":"/photos/daurian-redstart-1.webp","credit":"Laitche","license":"CC BY-SA 4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Daurian_redstart_(female)_in_Sakai,_Osaka,_February_2016_III.jpg"}'::jsonb, 'CC BY-SA 4.0', false, false)
