insert into public.taxa (id, korean_name, scientific_name, category, confusable_ids, clue, month_counts, photo, photo_license, cultivated, minor) values ('brown-eared-bulbul', '직박구리', 'Hypsipetes amaurotis', 'townbird', array['naumanns-thrush', 'dusky-thrush']::text[], '{"zoneIds":["Z4","Z3"],"where":"열매 달린 나무에 와요.","looks":["온몸이 회색이에요.","뺨에 밤색 무늬가 있어요.","삐이익 하고 크게 울어요."]}'::jsonb, array[3, 1, 2, 2, 0, 1, 0, 0, 0, 1, 1, 2]::integer[], '{"src":"/photos/brown-eared-bulbul-1.webp","credit":"Alpsdake","license":"CC BY-SA 3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hypsipetes_amaurotis_(Microscelis_amaurotis).JPG"}'::jsonb, 'CC BY-SA 3.0', false, false)
