insert into public.taxa (id, korean_name, scientific_name, category, confusable_ids, clue, month_counts, photo, photo_license, cultivated, minor) values ('japanese-tit', '박새', 'Parus minor', 'townbird', array['marsh-tit', 'varied-tit']::text[], '{"zoneIds":["Z3","Z4"],"where":"나뭇가지 사이를 바쁘게 옮겨 다녀요.","looks":["머리는 까맣고 뺨은 하얘요.","가슴에 까만 넥타이 무늬가 있어요."]}'::jsonb, array[2, 1, 1, 3, 0, 1, 1, 0, 0, 2, 1, 2]::integer[], '{"src":"/photos/japanese-tit-1.webp","credit":"Alpsdake","license":"CC BY-SA 3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Parus_minor_female.JPG"}'::jsonb, 'CC BY-SA 3.0', false, false)
